'use client';

import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { usePlayback } from './use-playback';
import { useReducedMotion } from './use-reduced-motion';
import './waveform-equalizer.css';

export interface WaveformEqualizerProps {
  /** Number of bars, capped at 32. */
  bars?: number;
  /** Multiplies the signal; 1 is normal. */
  sensitivity?: number;
  paused?: boolean;
  label: string;
  className?: string;
}

/**
 * Bars driven by a locally generated signal (no microphone, no audio). Each
 * bar eases toward its next level. A text line gives the overall level, and
 * reduced motion updates it once a second without animating the bars.
 */
export function WaveformEqualizer({
  bars = 16,
  sensitivity = 1,
  paused = false,
  label,
  className = '',
}: WaveformEqualizerProps) {
  const root = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const playing = usePlayback(root, paused);
  const count = Math.max(1, Math.min(32, bars));
  const [levels, setLevels] = useState(() =>
    Array.from({ length: count }, () => 0.2)
  );

  useEffect(() => {
    if (!playing) return;
    const start = performance.now();
    const tick = () => {
      const t = (performance.now() - start) / 1000;
      setLevels(
        Array.from({ length: count }, (_, i) => {
          // A few slow sines plus a little noise: a believable fake signal.
          const base =
            0.45 +
            0.25 * Math.sin(t * 2.1 + i * 0.5) +
            0.15 * Math.sin(t * 5.3 + i * 1.7);
          return Math.max(
            0.04,
            Math.min(1, (base + (Math.random() - 0.5) * 0.15) * sensitivity)
          );
        })
      );
    };
    tick();
    const timer = window.setInterval(tick, reduced ? 1000 : 110);
    return () => window.clearInterval(timer);
  }, [playing, count, sensitivity, reduced]);

  const average = levels.reduce((a, b) => a + b, 0) / levels.length;
  const word = !playing
    ? 'Paused'
    : average > 0.7
      ? 'Loud'
      : average > 0.4
        ? 'Moderate'
        : 'Quiet';

  return (
    <div ref={root} className={`mg-eq ${className}`} data-playing={playing}>
      <div className='mg-eq__bars' aria-hidden='true'>
        {levels.map((level, i) => (
          <span key={i} style={{ '--mg-level': level } as CSSProperties} />
        ))}
      </div>
      <p
        className='mg-eq__status'
        role='status'
        aria-label={`${label}: ${word}, ${Math.round(average * 100)}%`}
      >
        {label}: <strong>{word}</strong> · {Math.round(average * 100)}%
      </p>
    </div>
  );
}

.mg-eq {
  display: grid;
  gap: 8px;
  color: var(--mg-text, #ffffff);
}

.mg-eq__bars {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  height: 120px;
  padding: 10px;
  border-radius: 12px;
  background: var(--mg-raised, #262626);
}

.mg-eq__bars span {
  flex: 1;
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(
    to top,
    var(--mg-accent, #0047ff),
    #648aff 70%,
    var(--mg-accent, #0047ff)
  );
  transform: scaleY(var(--mg-level));
  transform-origin: bottom;
  transition: transform 110ms linear;
}

.mg-eq[data-playing='false'] .mg-eq__bars span {
  opacity: 0.5;
}

.mg-eq__status {
  margin: 0;
  color: #b8b8b8;
  font-size: 13px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-eq__bars span {
    transition: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
